$(function () {
  let image = &quot;Illustrations/PNJ/Gnome.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td class=&quot;symbole2&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Gnome.ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Gnome.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;gnomes&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Armure de babioles gnome&lt;div style=&quot;float:right;&quot;&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Races de la mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Inner Sea Races/Races de la mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoISR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;Transmutation&lt;/a&gt; faible ; &lt;b&gt;NLS&lt;/b&gt; 5 ; &lt;b&gt;Emplacement&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques-Sp&#233;cifiques.html&quot; title=&quot;Armures magiques sp&#233;cifiques&quot;&gt;armure&lt;/a&gt; ; &lt;b&gt;Prix&lt;/b&gt; 11.175 po ; &lt;b&gt;Poids&lt;/b&gt; 5 kg
&lt;div class=&quot;box&quot;&gt;Description&lt;/div&gt;
Une &lt;i&gt;armure de babioles gnome&lt;/i&gt; prot&#232;ge son porteur comme une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Cuir-Clout&#233;e-(Armure).html&quot; title=&quot;Armure de cuir clout&#233;e&quot;&gt;armure de cuir clout&#233;e&lt;/a&gt; +2&lt;/i&gt;, mais la myriade de colifichets m&#233;talliques qui l&#39;orne remplace les clous habituels. Un certain nombre de ces badges &#233;mettent une aura sp&#233;ciale ; chacun de ces badges peut &#234;tre retir&#233; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt;, auquel cas il se transforme en une version grandeur nature de l&#39;objet original. Le porteur reconna&#238;t automatiquement quels badges ont cette propri&#233;t&#233;, et seul le porteur peut les d&#233;tacher.&lt;br /&gt;&lt;br /&gt;Une &lt;i&gt;armure de babioles gnome&lt;/i&gt; compl&#232;te contient 20 badges qui repr&#233;sentent l&#39;&#233;quipement suivant : une flasque d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Acide-(Objet).html&quot; title=&quot;Acide&quot;&gt;acide&lt;/a&gt;, deux &lt;a class=&quot;pagelink&quot; href=&quot;B&#226;ton-&#201;clairant-(Objet).html&quot; title=&quot;B&#226;ton &#233;clairant&quot;&gt;b&#226;tons &#233;clairants&lt;/a&gt; allum&#233;s, une bouteille de &lt;a class=&quot;pagelink&quot; href=&quot;Vin-(Objet).html&quot; title=&quot;Vin&quot;&gt;bon vin&lt;/a&gt;, une &lt;a class=&quot;pagelink&quot; href=&quot;Couverture-(Objet).html&quot; title=&quot;Couverture&quot;&gt;couverture&lt;/a&gt; d&#39;hiver, deux flasques de &lt;a class=&quot;pagelink&quot; href=&quot;Feu-Gr&#233;geois-(Objet).html&quot; title=&quot;Feu gr&#233;geois&quot;&gt;feu gr&#233;geois&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Filet-(Arme).html&quot; title=&quot;Filet&quot;&gt;filet&lt;/a&gt; repli&#233;, une &lt;a class=&quot;pagelink&quot; href=&quot;Hache-De-Lancer-(Arme).html&quot; title=&quot;Hache de lancer&quot;&gt;hache de lancer&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Marteau-De-Guerre-(Arme).html&quot; title=&quot;Marteau de guerre&quot;&gt;marteau de guerre&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Palan-(Objet).html&quot; title=&quot;Palan&quot;&gt;palan&lt;/a&gt;, une &lt;a class=&quot;pagelink&quot; href=&quot;Pelle-(Objet).html&quot; title=&quot;Pelle&quot;&gt;pelle&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Pic-De-Guerre-Lourd-(Arme).html&quot; title=&quot;Pic de guerre lourd&quot;&gt;pic de guerre lourd&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Pied-De-Biche-(Objet).html&quot; title=&quot;Pied-de-biche&quot;&gt;pied-de-biche&lt;/a&gt;, une &lt;a class=&quot;pagelink&quot; href=&quot;Pierre-Tonnerre-(Objet).html&quot; title=&quot;Pierre tonnerre&quot;&gt;pierre tonnerre&lt;/a&gt;, une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Potions-Magiques.html&quot; title=&quot;Les potions magiques&quot;&gt;potion&lt;/a&gt; d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;&lt;/i&gt;, une &lt;i&gt;potion de &lt;a class=&quot;pagelink&quot; href=&quot;Restauration-Partielle.html&quot; title=&quot;Restauration partielle&quot;&gt;restauration partielle&lt;/a&gt;&lt;/i&gt;, deux &lt;a class=&quot;pagelink&quot; href=&quot;Sacoche-Immobilisante-(Objet).html&quot; title=&quot;Sacoche immobilisante&quot;&gt;sacoches immobilisantes&lt;/a&gt;, et une &lt;a class=&quot;pagelink&quot; href=&quot;Targe-(Armure).html&quot; title=&quot;Targe&quot;&gt;targe&lt;/a&gt;. Lorsqu&#39;il ne reste plus que 10 badges ou moins &#224; l&#39;armure, elle est r&#233;duite &#224; une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Cuir-Clout&#233;e-(Armure).html&quot; title=&quot;Armure de cuir clout&#233;e&quot;&gt;armure de cuir clout&#233;e&lt;/a&gt; +1&lt;/i&gt; jusqu&#39;&#224; ce que suffisamment de badges y soient replac&#233;s. Si tous les objets sont retir&#233;s, l&#39;armure devient une armure de cuir clout&#233;e &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures#Armuresmaitre.html&quot; title=&quot;armure de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt; non-magique.&lt;br /&gt;&lt;br /&gt;Tant que l&#39;armure est magique, le porteur peut y replacer des badges en lan&#231;ant &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-Dobjet.html&quot; title=&quot;R&#233;duction d&amp;#39;objet&quot;&gt;r&#233;duction d&#39;objet&lt;/a&gt;&lt;/i&gt; sur l&#39;objet appropri&#233; alors qu&#39;il porte l&#39;armure et que l&#39;objet est en contact avec elle. Cela peut m&#234;me convertir les potions appropri&#233;es en badges, bien que &lt;i&gt;r&#233;duction d&#39;objet&lt;/i&gt; ne fonctionne normalement pas sur les objets magiques. Seuls les objets correspondant exactement aux badges manquants peuvent &#234;tre fusionn&#233;s &#224; l&#39;armure. Fusionner une potion r&#233;duit son &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; au minimum pour ce niveau de sort. Les objets produits par une &lt;i&gt;armure de babioles gnome&lt;/i&gt; sont adapt&#233;s &#224; la taille de l&#39;armure, donc une armure typique taill&#233;e pour un &lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;gnome&lt;/a&gt; produit des objets adapt&#233;s aux cr&#233;atures de &lt;a class=&quot;pagelink&quot; href=&quot;Petites-Et-Grandes-Cr&#233;atures#Tableautailles.html&quot; title=&quot;taille P&quot;&gt;taille P&lt;/a&gt;.
&lt;div class=&quot;box&quot;&gt;Cr&#233;ation&lt;/div&gt;
&lt;b&gt;Conditions&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Darmes-Et-Armures-Magiques.html&quot; title=&quot;Cr&#233;ation d&amp;#39;armes et armures magiques&quot;&gt;Cr&#233;ation d&#39;armes et armures magiques&lt;/a&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-Dobjet.html&quot; title=&quot;R&#233;duction d&amp;#39;objet&quot;&gt;r&#233;duction d&#39;objet&lt;/a&gt;&lt;/i&gt;, le cr&#233;ateur doit &#234;tre un &lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;gnome&lt;/a&gt; ; &lt;b&gt;Co&#251;t&lt;/b&gt; 5.675 po
&lt;/div&gt;
